def intake(op_id, target_key, annual_sales_cents,
           normalized_profit_cents, largest_customer_bps):
    values = (annual_sales_cents, normalized_profit_cents,
              largest_customer_bps)
    if any(type(value) is not int for value in values):
        raise ValueError("Use integer cents and integer basis points")
    if not target_key or annual_sales_cents <= 0:
        raise ValueError("Target identity and positive annual sales required")
    if not 0 <= largest_customer_bps <= 10000:
        raise ValueError("Concentration must lie between zero and 10000")
    payload = [target_key] + list(values)
    fingerprint = digest(payload)
    margin_bps = normalized_profit_cents * 10000 // annual_sales_cents
    score = (
        (50 if margin_bps >= 1300 else 25 if margin_bps >= 800 else 0)
        + (50 if largest_customer_bps <= 1500
           else 25 if largest_customer_bps <= 3000 else 0)
    )

    def work(db):
        prior = db.execute(
            "SELECT id, payload_hash FROM deals WHERE target_key=?",
            (target_key,),
        ).fetchone()
        if prior:
            if prior[1] != fingerprint:
                raise ValueError("Changed intake requires reviewed versioning")
            return prior[0]
        cursor = db.execute(
            "INSERT INTO deals "
            "(target_key,payload_hash,annual_sales_cents,"
            "normalized_profit_cents,largest_customer_bps,screen_score) "
            "VALUES (?,?,?,?,?,?)",
            (target_key, fingerprint, annual_sales_cents,
             normalized_profit_cents, largest_customer_bps, score),
        )
        return cursor.lastrowid

    return transact("intake:" + op_id, payload, work)

def add_evidence(op_id, deal_id, kind, reference, sha256):
    if not kind or not reference:
        raise ValueError("Evidence kind and reviewed reference required")
    if len(sha256) != 64 or any(c not in "0123456789abcdef" for c in sha256):
        raise ValueError("Use a lowercase SHA-256 document digest")
    payload = [deal_id, kind, reference, sha256]

    def work(db):
        row = db.execute(
            "SELECT reference,sha256 FROM evidence WHERE deal_id=? AND kind=?",
            (deal_id, kind),
        ).fetchone()
        if row:
            if tuple(row) != (reference, sha256):
                raise ValueError("Existing evidence cannot be overwritten")
            return kind
        db.execute(
            "INSERT INTO evidence(deal_id,kind,reference,sha256) VALUES(?,?,?,?)",
            payload,
        )
        return kind

    return transact("evidence:" + op_id, payload, work)

def advance(op_id, deal_id, next_state):
    sequence = {
        "intake": "verified",
        "verified": "escrow_ready",
        "escrow_ready": "closed",
    }
    requirements = {
        "verified": {"qoe", "tax", "employment", "licenses", "liens"},
        "escrow_ready": {"lender_terms", "signed_purchase", "funds_memo"},
        "closed": {"closing_binder", "bank_settlement"},
    }

    def work(db):
        row = db.execute(
            "SELECT state,version FROM deals WHERE id=?", (deal_id,)
        ).fetchone()
        if not row or sequence.get(row[0]) != next_state:
            raise ValueError("Invalid predecessor state")
        present = {
            item[0] for item in db.execute(
                "SELECT kind FROM evidence WHERE deal_id=?", (deal_id,)
            )
        }
        missing = requirements[next_state] - present
        if missing:
            raise ValueError("Missing reviewed evidence: " + ", ".join(sorted(missing)))
        cursor = db.execute(
            "UPDATE deals SET state=?,version=version+1 WHERE id=? AND version=?",
            (next_state, deal_id, row[1]),
        )
        if cursor.rowcount != 1:
            raise RuntimeError("State version changed")
        return {"state": next_state, "version": row[1] + 1}

    return transact("advance:" + op_id, [deal_id, next_state], work)

from datetime import date

ACCOUNTS = {
    "1000": "Cash",
    "1100": "Trade receivables",
    "1500": "Acquired assets",
    "2000": "Trade payables",
    "2500": "Acquisition debt",
    "3000": "Owner equity",
    "4000": "Operating sales",
    "5000": "Direct delivery expense",
    "6100": "Operating overhead",
    "7100": "Interest expense",
}

def post(source, event_key, effective_date, memo, entries):
    date.fromisoformat(effective_date)
    entries = [list(item) for item in entries]
    if not source or not event_key or not memo or len(entries) < 2:
        raise ValueError("Source, event, memo, and balanced lines required")
    for account, cents in entries:
        if account not in ACCOUNTS or type(cents) is not int or cents == 0:
            raise ValueError("Use supported accounts and nonzero integer cents")
    if sum(item[1] for item in entries) != 0:
        raise ValueError("Journal debits and credits must balance")
    if sum(item[0] == "1000" for item in entries) > 1:
        raise ValueError("Use one cash line per bank transaction")
    payload = [source, event_key, effective_date, memo, entries]

    def work(db):
        cursor = db.execute(
            "INSERT INTO journals(source,event_key,effective_date,memo) "
            "VALUES(?,?,?,?)",
            (source, event_key, effective_date, memo),
        )
        journal_id = cursor.lastrowid
        db.executemany(
            "INSERT INTO lines(journal_id,line_number,account,cents) VALUES(?,?,?,?)",
            [(journal_id, number, account, cents)
             for number, (account, cents) in enumerate(entries, 1)],
        )
        return journal_id

    operation = "post:" + digest([source, event_key])
    return transact(operation, payload, work)

