def import_statement(bank_account, bank_event, effective_date, cents):
    date.fromisoformat(effective_date)
    if not bank_account or not bank_event or type(cents) is not int or cents == 0:
        raise ValueError("Stable bank identifiers and signed integer cents required")
    payload = [bank_account, bank_event, effective_date, cents]

    def work(db):
        cursor = db.execute(
            "INSERT INTO statements(bank_account,bank_event,effective_date,cents) "
            "VALUES(?,?,?,?)", payload,
        )
        return cursor.lastrowid

    operation = "statement:" + digest([bank_account, bank_event])
    return transact(operation, payload, work)

def match_cash(op_id, journal_id, statement_id):
    def work(db):
        cash = db.execute(
            "SELECT cents FROM lines WHERE journal_id=? AND account='1000'",
            (journal_id,),
        ).fetchall()
        bank = db.execute(
            "SELECT cents FROM statements WHERE id=?", (statement_id,)
        ).fetchone()
        if len(cash) != 1 or not bank or cash[0][0] != bank[0]:
            raise ValueError("One ledger cash amount must equal the bank amount")
        prior = db.execute(
            "SELECT statement_id FROM matches WHERE journal_id=?", (journal_id,)
        ).fetchone()
        if prior:
            if prior[0] != statement_id:
                raise ValueError("Journal already matched to another bank record")
            return {"journal_id": journal_id, "statement_id": statement_id}
        db.execute(
            "INSERT INTO matches(journal_id,statement_id) VALUES(?,?)",
            (journal_id, statement_id),
        )
        return {"journal_id": journal_id, "statement_id": statement_id}

    return transact("match:" + op_id, [journal_id, statement_id], work)
